// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {ICredit} from "./interfaces/ICredit.sol";

/// @title Exchange
/// @notice CREDIT order book priced as a discount off face value, paid in USDC.
///         Sellers escrow CREDIT at a discount level; buyers fill from the deepest
///         discount down (FIFO within a level) and pay a platform fee on top.
/// @dev CREDIT and USDC are both 6 decimals, so 1 CREDIT at 0% off costs 1 USDC.
///      All payouts (sellers, affiliates, fee recipient) are pull-based via `claim`.
contract Exchange is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using SafeERC20 for ICredit;

    uint256 public constant BPS = 10_000;
    uint256 public constant TICK_BPS = 250;
    uint256 public constant MAX_DISCOUNT_BPS = 5_000;
    uint256 public constant LEVELS = MAX_DISCOUNT_BPS / TICK_BPS + 1;
    uint256 public constant MAX_FEE_BPS = 1_000;
    /// @notice Smallest order a seller can post: 1 CREDIT. Keeps queue spam expensive.
    uint256 public constant MIN_ORDER = 1e6;
    /// @notice Max queue entries a single buy may touch (fills + skipped cancels).
    uint256 public constant MAX_STEPS = 128;

    struct Order {
        address seller;
        uint16 discountBps;
        uint96 remaining;
        /// @dev Total sold so far; survives `cancel`, which zeroes `remaining`.
        uint96 filled;
        bool cancelled;
    }

    IERC20 public immutable usdc;
    ICredit public immutable credit;

    uint16 public feeBps;
    uint16 public affiliateBps;
    address public feeRecipient;

    uint256 public nextOrderId = 1;
    mapping(uint256 id => Order) public orders;
    mapping(uint256 level => uint256[] ids) private _queue;
    mapping(uint256 level => uint256) public queueHead;
    mapping(address seller => uint256[] ids) private _sellerOrders;
    uint256[LEVELS] private _liquidity;

    /// @notice USDC owed to sellers, affiliates and the fee recipient.
    mapping(address => uint256) public claimable;

    event OrderPlaced(uint256 indexed id, address indexed seller, uint16 discountBps, uint256 amount);
    event OrderCancelled(uint256 indexed id, address indexed seller, uint256 refunded);
    event OrderFilled(uint256 indexed id, address indexed seller, address indexed buyer, uint256 credits, uint256 cost);
    event Bought(
        address indexed buyer,
        address indexed recipient,
        bytes32 indexed account,
        address referrer,
        uint256 credits,
        uint256 creditPrice,
        uint256 fee
    );
    event Claimed(address indexed to, uint256 amount);
    event FeesUpdated(uint16 feeBps, uint16 affiliateBps);
    event FeeRecipientUpdated(address feeRecipient);

    error InvalidDiscount();
    error OrderTooSmall();
    error ZeroAmount();
    error ZeroAddress();
    error NotSeller();
    error OrderClosed();
    error InsufficientLiquidity(uint256 shortfall);
    error SlippageExceeded(uint256 total, uint256 maxTotal);
    error TooManySteps();
    error InvalidFees();

    constructor(
        address owner_,
        IERC20 usdc_,
        ICredit credit_,
        address feeRecipient_,
        uint16 feeBps_,
        uint16 affiliateBps_
    ) Ownable(owner_) {
        usdc = usdc_;
        credit = credit_;
        _setFeeRecipient(feeRecipient_);
        _setFees(feeBps_, affiliateBps_);
    }

    // ── sellers ──────────────────────────────────────────────────────────

    /// @notice Escrow `amount` CREDIT for sale at `discountBps` off face value.
    function sell(uint256 amount, uint16 discountBps) external nonReentrant whenNotPaused returns (uint256 id) {
        if (discountBps % TICK_BPS != 0 || discountBps > MAX_DISCOUNT_BPS) revert InvalidDiscount();
        if (amount < MIN_ORDER) revert OrderTooSmall();

        id = nextOrderId++;
        uint256 level = discountBps / TICK_BPS;
        orders[id] = Order({
            seller: msg.sender,
            discountBps: discountBps,
            remaining: SafeCast.toUint96(amount),
            filled: 0,
            cancelled: false
        });
        _queue[level].push(id);
        _sellerOrders[msg.sender].push(id);
        _liquidity[level] += amount;

        credit.safeTransferFrom(msg.sender, address(this), amount);
        emit OrderPlaced(id, msg.sender, discountBps, amount);
    }

    /// @notice Withdraw the unfilled remainder of an order. Allowed while paused.
    function cancel(uint256 id) external nonReentrant {
        Order storage order = orders[id];
        if (order.seller != msg.sender) revert NotSeller();
        uint256 refund = order.remaining;
        if (refund == 0) revert OrderClosed();

        order.remaining = 0;
        order.cancelled = true;
        _liquidity[order.discountBps / TICK_BPS] -= refund;

        credit.safeTransfer(msg.sender, refund);
        emit OrderCancelled(id, msg.sender, refund);
    }

    /// @notice Pay out everything owed to the caller in USDC.
    function claim() external nonReentrant returns (uint256 amount) {
        amount = claimable[msg.sender];
        if (amount == 0) revert ZeroAmount();
        claimable[msg.sender] = 0;
        usdc.safeTransfer(msg.sender, amount);
        emit Claimed(msg.sender, amount);
    }

    // ── buyers ───────────────────────────────────────────────────────────

    /// @notice Buy exactly `credits` CREDIT and send them to `recipient`.
    /// @param maxTotal Most USDC (price + fee) the caller will pay.
    /// @param referrer Affiliate credited with part of the fee, or address(0).
    function buy(uint256 credits, uint256 maxTotal, address recipient, address referrer)
        external
        nonReentrant
        whenNotPaused
        returns (uint256 total)
    {
        if (recipient == address(0)) revert ZeroAddress();
        total = _buy(credits, maxTotal, recipient, bytes32(0), referrer);
        credit.safeTransfer(recipient, credits);
    }

    /// @notice Buy `credits` and burn them straight into the API balance of `account`.
    function buyAndActivate(uint256 credits, uint256 maxTotal, bytes32 account, address referrer)
        external
        nonReentrant
        whenNotPaused
        returns (uint256 total)
    {
        total = _buy(credits, maxTotal, address(0), account, referrer);
        credit.activate(credits, account);
    }

    /// @notice Clear cancelled orders from the front of a level's queue.
    function prune(uint16 discountBps, uint256 maxSteps) external {
        uint256 level = discountBps / TICK_BPS;
        uint256[] storage q = _queue[level];
        uint256 head = queueHead[level];
        for (uint256 i; i < maxSteps && head < q.length && orders[q[head]].remaining == 0; ++i) {
            ++head;
        }
        queueHead[level] = head;
    }

    // ── views ────────────────────────────────────────────────────────────

    /// @notice CREDIT available at every level; index i is `i * TICK_BPS` off.
    function getBook() external view returns (uint256[LEVELS] memory) {
        return _liquidity;
    }

    /// @notice Price `credits` against the current book without touching state.
    function quote(uint256 credits)
        external
        view
        returns (uint256 creditPrice, uint256 fee, uint256 total, uint256 filled)
    {
        uint256 remaining = credits;
        for (uint256 i = LEVELS; i > 0 && remaining > 0; --i) {
            uint256 take = Math.min(remaining, _liquidity[i - 1]);
            if (take == 0) continue;
            creditPrice += _cost(take, (i - 1) * TICK_BPS);
            remaining -= take;
        }
        filled = credits - remaining;
        fee = _fee(creditPrice);
        total = creditPrice + fee;
    }

    function sellerOrderCount(address seller) external view returns (uint256) {
        return _sellerOrders[seller].length;
    }

    /// @notice A page of `seller`'s orders, newest first, including closed ones.
    function getSellerOrders(address seller, uint256 offset, uint256 limit)
        external
        view
        returns (uint256[] memory ids, Order[] memory page)
    {
        uint256[] storage all = _sellerOrders[seller];
        uint256 n = offset >= all.length ? 0 : Math.min(limit, all.length - offset);
        ids = new uint256[](n);
        page = new Order[](n);
        for (uint256 i; i < n; ++i) {
            uint256 id = all[all.length - 1 - offset - i];
            ids[i] = id;
            page[i] = orders[id];
        }
    }

    function queueLength(uint16 discountBps) external view returns (uint256) {
        return _queue[discountBps / TICK_BPS].length;
    }

    // ── admin ────────────────────────────────────────────────────────────

    function setFees(uint16 feeBps_, uint16 affiliateBps_) external onlyOwner {
        _setFees(feeBps_, affiliateBps_);
    }

    function setFeeRecipient(address feeRecipient_) external onlyOwner {
        _setFeeRecipient(feeRecipient_);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // ── internals ────────────────────────────────────────────────────────

    function _buy(uint256 credits, uint256 maxTotal, address recipient, bytes32 account, address referrer)
        private
        returns (uint256 total)
    {
        if (credits == 0) revert ZeroAmount();

        uint256 creditPrice = _fill(credits);
        uint256 fee = _fee(creditPrice);
        total = creditPrice + fee;
        if (total > maxTotal) revert SlippageExceeded(total, maxTotal);

        uint256 referral =
            referrer != address(0) && referrer != msg.sender ? Math.min(fee, (creditPrice * affiliateBps) / BPS) : 0;
        if (referral > 0) claimable[referrer] += referral;
        claimable[feeRecipient] += fee - referral;

        emit Bought(msg.sender, recipient, account, referral > 0 ? referrer : address(0), credits, creditPrice, fee);
        usdc.safeTransferFrom(msg.sender, address(this), total);
    }

    /// @dev Walks levels from deepest discount down, FIFO within a level.
    function _fill(uint256 credits) private returns (uint256 creditPrice) {
        uint256 remaining = credits;
        uint256 steps;
        for (uint256 i = LEVELS; i > 0 && remaining > 0; --i) {
            uint256 level = i - 1;
            if (_liquidity[level] == 0) continue;

            uint256[] storage q = _queue[level];
            uint256 head = queueHead[level];
            while (remaining > 0 && head < q.length) {
                if (++steps > MAX_STEPS) revert TooManySteps();
                uint256 id = q[head];
                Order storage order = orders[id];
                uint256 available = order.remaining;
                if (available == 0) {
                    ++head;
                    continue;
                }
                uint256 take = Math.min(remaining, available);
                uint256 cost = _cost(take, order.discountBps);

                // forge-lint: disable-next-line(unsafe-typecast) -- available is itself a uint96
                order.remaining = uint96(available - take);
                // forge-lint: disable-next-line(unsafe-typecast) -- take <= available, itself a uint96
                order.filled += uint96(take);
                _liquidity[level] -= take;
                claimable[order.seller] += cost;
                creditPrice += cost;
                remaining -= take;
                if (take == available) ++head;

                emit OrderFilled(id, order.seller, msg.sender, take, cost);
            }
            queueHead[level] = head;
        }
        if (remaining > 0) revert InsufficientLiquidity(remaining);
    }

    /// @dev Rounds up so sellers never receive less than their discount implies.
    function _cost(uint256 credits, uint256 discountBps) private pure returns (uint256) {
        return Math.mulDiv(credits, BPS - discountBps, BPS, Math.Rounding.Ceil);
    }

    function _fee(uint256 creditPrice) private view returns (uint256) {
        return Math.mulDiv(creditPrice, feeBps, BPS, Math.Rounding.Ceil);
    }

    function _setFees(uint16 feeBps_, uint16 affiliateBps_) private {
        if (feeBps_ > MAX_FEE_BPS || affiliateBps_ > feeBps_) revert InvalidFees();
        feeBps = feeBps_;
        affiliateBps = affiliateBps_;
        emit FeesUpdated(feeBps_, affiliateBps_);
    }

    function _setFeeRecipient(address feeRecipient_) private {
        if (feeRecipient_ == address(0)) revert ZeroAddress();
        feeRecipient = feeRecipient_;
        emit FeeRecipientUpdated(feeRecipient_);
    }
}

